import {FormEvent,useEffect,useState} from 'react';import {Link,useLocation,useNavigate,useParams,useSearchParams} from 'react-router';import {ArrowRight,BookOpen,ChevronRight,FileText,History,Landmark,Library,MessagesSquare,Search,Settings,ShieldCheck,SquarePen,Trash2,Vote} from 'lucide-react';import {discussionCategories,proposalTabs,workflow} from './data/constitution';import {learningQuizQuestions,learningActivities,learningCaseStudies} from './data/learningQuestions';import {TANZANIA_REGIONS,TANZANIA_REGION_NAMES} from './data/tanzaniaLocations';import {ConstitutionChapter,constitutionSources,loadArticleByNumber,loadConstitutionExplanation,loadChapters,searchConstitution,checkSourceIntegrity,loadSchedules,loadSchedule,searchSchedules,normalizeArticleText} from './services/constitution';import {supabase} from './lib/supabase';import {useLanguage} from './lib/language';import {getDocument,GlobalWorkerOptions} from 'pdfjs-dist';import pdfWorker from 'pdfjs-dist/build/pdf.worker.mjs?url';
GlobalWorkerOptions.workerSrc=pdfWorker;
async function extractLibraryText(file:File){if(file.type==='application/pdf'||file.name.toLowerCase().endsWith('.pdf')){const pdf=await getDocument({data:new Uint8Array(await file.arrayBuffer())}).promise;const pages:string[]=[];for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i),content=await page.getTextContent();pages.push(content.items.map((x:any)=>String(x.str||'')+(x.hasEOL?'\n':' ')).join(''))}return pages.join('\n')}return await file.text()}
function convertLibraryTextToJson(text:string,type='katiba'){const clean=text.replace(/\r/g,'').replace(/[ \t]+/g,' ').trim();if(type==='sheria'){const marker=clean.search(/An Act to establish a code of criminal law\./i),arrangement=marker>0?clean.slice(0,marker):clean.slice(0,35000),body=marker>0?clean.slice(marker):clean;const titles=new Map<string,string>();for(const m of arrangement.matchAll(/^\s*(\d+[A-Z]?)(?:\.\-|\.)\s+([^\n]+)/gmi))titles.set(m[1],m[2].trim());const ordered=[...titles.keys()];const hits:{section:string;index:number}[]=[];let cursor=0;for(const section of ordered){const re=new RegExp('^.{0,80}?\\b'+section.replace(/[^0-9A-Z]/gi,'')+'(?:\\.\\-|\\.)\\s*','gmi');re.lastIndex=cursor;const m=re.exec(body);if(m){hits.push({section,index:m.index});cursor=m.index+1}}const out=hits.map((h,i)=>{const raw=body.slice(h.index,i+1<hits.length?hits[i+1].index:body.length).replace(/^\s*Penal Code\s+\[CAP\. 16 R\.E\. 2022\]\s*$/gmi,'').replace(/^\s*\d{1,3}\s*$/gm,'').replace(/\n{3,}/g,'\n\n').trim();const before=body.slice(Math.max(0,h.index-1800),h.index),parts=[...before.matchAll(/^\s*PART\s+([IVXLCDM]+)\s*\n\s*([^\n]+)/gmi)],chapters=[...before.matchAll(/^\s*CHAPTER\s+([IVXLCDM]+)\s*\n\s*([^\n]+)/gmi)];return {section:h.section,title:titles.get(h.section)||'Section '+h.section,text:raw,part:parts.length?'PART '+parts[parts.length-1][1]+' â€” '+parts[parts.length-1][2].trim():'',chapter:chapters.length?'CHAPTER '+chapters[chapters.length-1][1]+' â€” '+chapters[chapters.length-1][2].trim():'',subsections:raw.match(/\(\d+\)[\s\S]*?(?=\(\d+\)|$)/g)?.map(x=>x.trim())||[]}});return out.length?out:[{section:'1',title:'Full document',text:clean,part:'',chapter:'',subsections:[]}]}const matches=[...clean.matchAll(/(?:^|\n|\s)(?:IBARA|Ibara)\s+(?:YA\s+)?(\d+[A-Za-z]?)[\.:\-]?\s*/g)];if(!matches.length)return [{ibara:'1',jina:'Nyaraka kamili',maudhui:clean,vifungu:[]}];return matches.map((m,i)=>{const start=(m.index||0)+m[0].length,end=i+1<matches.length?(matches[i+1].index||clean.length):clean.length,body=clean.slice(start,end).trim(),lines=body.split('\n').map(x=>x.trim()).filter(Boolean),first=lines[0]||'';return {ibara:m[1],jina:first.length<=180?first:'Ibara '+m[1],maudhui:body,vifungu:body.match(/\(\d+\)[\s\S]*?(?=\(\d+\)|$)/g)?.map(x=>x.trim())||[]}})}

function highlightSearch(text:string,query:string){const terms=query.trim().split(/\s+/).filter(Boolean);if(!terms.length)return text;const lower=text.toLocaleLowerCase('sw');const ranges=terms.flatMap(t=>{const out:[number,number][]=[];let at=0,needle=t.toLocaleLowerCase('sw');while((at=lower.indexOf(needle,at))>=0){out.push([at,at+needle.length]);at+=needle.length}return out}).sort((a,b)=>a[0]-b[0]);if(!ranges.length)return text;const merged:[number,number][]=[];for(const r of ranges){const last=merged[merged.length-1];if(last&&r[0]<=last[1])last[1]=Math.max(last[1],r[1]);else merged.push([...r])}const out:any[]=[];let pos=0;merged.forEach((r,i)=>{if(r[0]>pos)out.push(text.slice(pos,r[0]));out.push(<mark key={i}>{text.slice(r[0],r[1])}</mark>);pos=r[1]});if(pos<text.length)out.push(text.slice(pos));return out}
function constitutionRefHref(ref:string){const article=ref.match(/(?:Ibara(?:\s+ya)?|Article)\s+(\d+[A-Za-z]?)/i)?.[1];if(!article)return '/katiba/doc-union-1977';const clause=ref.match(/(?:Ibara(?:\s+ya)?|Article)\s+\d+[A-Za-z]?\s*\((\d+)\)/i)?.[1];return '/katiba/doc-union-1977/'+encodeURIComponent(article)+(clause?'?kifungu='+encodeURIComponent(clause):'')}
function IdentityBadge({profile}:{profile:any}){if(!profile)return null;if(profile.account_type==='individual'&&profile.nida_verified)return <span className="identityBadge verified">âœ“ Verified Citizen</span>;if(profile.account_type!=='individual'&&profile.organization_verified)return <span className="identityBadge organization">âœ“ Verified {String(profile.account_type||'institution').replaceAll('_',' ')}</span>;return null}
function PublicIdentity({profile,fallback='Mwananchi'}:{profile:any,fallback?:string}){const name=profile?.organization_verified&&profile?.organization_name?profile.organization_name:(profile?.display_name||fallback);const inner=<><b>{name}</b><IdentityBadge profile={profile}/></>;return profile?.id?<Link className="publicIdentity" to={'/profile/'+profile.id}>{inner}</Link>:<span className="publicIdentity">{inner}</span>}
