 useEffect(()=>{let live=true;if(!source){setLoading(false);return}setLoading(true);Promise.all([loadChapters(source.id),loadSchedules(source.id)]).then(([x,s])=>{if(live){setChapters(x);setSchedules(s);setLoading(false)}});return()=>{live=false}},[source?.id]);
